      "id": 2,
      "claim": "The src oncogene encodes the protein pp60src, which has intrinsic tyrosine‑kinase activity.",
      "evidence": "Molecular studies of viral src (v‑src) and cellular src (c‑src) demonstrate that pp60src is a non‑receptor tyrosine kinase that phosphorylates tyrosine residues on cellular proteins.",
      "weight": 0.45,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "The activity described (specific addition of phosphate groups to cellular proteins) matches a tyrosine kinase, which corresponds to option D.",
      "evidence": "Among the answer choices, only “Tyrosine kinase” (D) denotes an enzyme that adds phosphate groups to proteins; the other options are a phosphatase (removes phosphates), adenylate cyclase (produces cAMP), and a G‑protein‑linked receptor (a membrane receptor, not a kinase).",
      "weight": 0.20,
      "depends_on": [1, 2]
    }
  ],
  "answer": "D",
  "confidence": 0.99,
  "considered": [
    {
      "answer": "A",
      "reason_rejected": "Protein phosphatases remove phosphate groups (dephosphorylation), not add them."
    },
    {
      "answer": "B",
      "reason_rejected": "Adenylate cyclase synthesizes cAMP from ATP and does not phosphorylate proteins."
    },
    {
      "answer": "C",
      "reason_rejected": "G‑protein‑linked receptors are membrane receptors that signal via G proteins; they are not enzymes that add phosphate groups."
    }
  ]
